ALTER TABLE "get_started_claims" ADD CONSTRAINT "get_started_slot_check" CHECK (("get_started_claims"."status" <> 'granted' AND "get_started_claims"."reward_slot" IS NULL) OR ("get_started_claims"."status" = 'granted' AND (("get_started_claims"."quest_key" = 'invite' AND "get_started_claims"."reward_slot" BETWEEN 1 AND 15 AND "get_started_claims"."reward_slot" IS NOT NULL) OR ("get_started_claims"."quest_key" IN ('imessage', 'workflow', 'share') AND "get_started_claims"."reward_slot" = 1 AND "get_started_claims"."reward_slot" IS NOT NULL) OR ("get_started_claims"."quest_key" = 'connector' AND ("get_started_claims"."reward_slot" IS NULL OR "get_started_claims"."reward_slot" BETWEEN 1 AND 10)) OR ("get_started_claims"."quest_key" IN ('slack', 'checkin') AND "get_started_claims"."reward_slot" IS NULL)))) NOT VALID;--> statement-breakpoint
ALTER TABLE "get_started_claims" VALIDATE CONSTRAINT "get_started_slot_check";
